def generated_loss(batch, model_output, extra):
    # Required: winner/loser log-probs (prefer batch, fallback to model_output).
    log_prob_w = batch.get("log_prob_w", None)
    if log_prob_w is None:
        log_prob_w = model_output.get("log_prob_w", model_output.get("chosen_logprob", None))

    log_prob_l = batch.get("log_prob_l", None)
    if log_prob_l is None:
        log_prob_l = model_output.get("log_prob_l", model_output.get("rejected_logprob", None))

    alpha = 1.0
    beta = 0.01
    gmax = 5.0
    bmax = 0.1

    delta = log_prob_w - log_prob_l
    base = -ops.logsigmoid(alpha * delta)

    # Objective signal: delta_z (use raw/clamped to avoid z-score washout on tiny batches).
    gap_signal = batch.get("delta_z", None)
    if gap_signal is None:
        gap_signal = model_output.get("delta_z", None)

    if gap_signal is None:
        bias = ops.zeros_like(base)
    else:
        g = ops.clamp(gap_signal, -gmax, gmax)
        bias = ops.clamp(beta * g, -bmax, bmax)

    # Optional external per-example weight.
    base_weight = batch.get("weight", model_output.get("weight", None))
    if base_weight is not None:
        return (base_weight * (base + bias)).mean()

    return (base + bias).mean()

def generated_loss(batch, model_output, extra):
    # Required inputs: winner/loser log-probabilities.
    log_prob_w = None
    log_prob_l = None
    if isinstance(model_output, dict):
        log_prob_w = model_output.get("log_prob_w", None)
        log_prob_l = model_output.get("log_prob_l", None)

    # If missing required tensors, return a safe zero anchored to any available tensor.
    if log_prob_w is None or log_prob_l is None:
        anchor = None
        if isinstance(model_output, dict):
            for v in model_output.values():
                anchor = v
                break
        if anchor is None and isinstance(batch, dict):
            for v in batch.values():
                anchor = v
                break
        if anchor is None and isinstance(extra, dict):
            for v in extra.values():
                anchor = v
                break
        if anchor is None:
            return 0.0
        return (anchor * 0.0).mean()

    # Optional signals.
    delta_z = None
    if isinstance(extra, dict):
        delta_z = extra.get("delta_z", extra.get("gap", None))
    if delta_z is None and isinstance(batch, dict):
        delta_z = batch.get("delta_z", batch.get("gap", None))

    base_weight = None
    if isinstance(extra, dict):
        base_weight = extra.get("weight", None)
    if base_weight is None and isinstance(batch, dict):
        base_weight = batch.get("weight", None)

    # Hyperparams (read-only; no global state).
    hp = extra.get("hyperparams", {}) if isinstance(extra, dict) else {}
    alpha = float((extra.get("alpha") if isinstance(extra, dict) else None) or hp.get("alpha", 1.0))
    k = float((extra.get("k") if isinstance(extra, dict) else None) or hp.get("k", 1.0))
    eps = float((extra.get("eps") if isinstance(extra, dict) else None) or hp.get("eps", 0.1))
    w_max = float((extra.get("w_max") if isinstance(extra, dict) else None) or hp.get("w_max", 10.0))
    gap_fallback = float((extra.get("gap_fallback") if isinstance(extra, dict) else None) or hp.get("gap_fallback", 0.0))

    delta = log_prob_w - log_prob_l
    base = -ops.logsigmoid(alpha * delta)

    if delta_z is None:
        gap = delta * 0.0 + gap_fallback
    else:
        gap = ops.zscore(delta_z)

    w = ops.softplus(k * gap) + eps
    w = ops.clamp(w, 0.0, w_max)
    if base_weight is not None:
        w = w * base_weight

    return (w * base).mean()
